#!/usr/bin/env python3
"""Compact offline delivered-output viewer; no image generation or raw output links."""
import argparse,json
from pathlib import Path
from qa import read,sha,atomic

def main():
 ap=argparse.ArgumentParser();ap.add_argument('--batch',required=True,type=Path);args=ap.parse_args();batch=args.batch.resolve();m=read(batch/'manifest.json');delivery=read(batch/'accepted_delivery.json');runs={r['id']:r for r in read(batch/'selected_run_state.json')['images']};d={r['id']:r for r in delivery['images']};cards=[]
 assert delivery['manifest_sha256']==sha(batch/'manifest.json') and delivery['output_review_sha256']==sha(batch/'independent_output_review.json') and delivery['mechanical_audit_sha256']==sha(batch/'mechanical_audit.json')
 for group in m['groups']:
  for row in group['versions']:
   id=row['batch_id'];entry=d[id];source=Path(row['source']);after=Path(entry['path']);assert sha(source)==row['source_sha256']==entry['source_sha256'] and sha(after)==entry['sha256'];accepted=entry['delivery']=='cleaned';regions=[]
   if accepted:
    assert after.resolve()==(batch/'accepted_outputs'/id/'after.webp').resolve();r=read(after.parent/'result.json');assert r['output_sha256']==entry['sha256'];regions=r['regions']
   else:assert after.resolve()==source.resolve() and entry['sha256']==row['source_sha256']
   cards.append({'id':id,'concept':group.get('group_key',group['group_id']),'style':row['style'],'dimensions':row['dimensions'],'source':source.resolve().as_uri(),'after':after.resolve().as_uri(),'source_bytes':source.stat().st_size,'after_bytes':after.stat().st_size,'accepted':accepted,'status':runs[id]['status'],'role':entry.get('role'),'reference':entry.get('reference',False),'review_required':entry.get('review_required',True),'newly_processed':entry.get('newly_processed',True),'reason':entry['reason'],'source_sha256':row['source_sha256'],'output_sha256':entry['sha256'],'regions':regions})
 assert len(cards)==len(d)
 payload=json.dumps(cards,ensure_ascii=False,separators=(',',':')).replace('<','\\u003c')
 page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>People cleanup review</title><style>
body{font:14px system-ui;margin:0;background:#eee;color:#222}header{position:sticky;top:0;background:white;padding:12px;display:flex;flex-wrap:wrap;gap:10px;z-index:2}button,select,input{font:inherit;padding:5px}main{padding:12px}.meta{background:white;padding:12px;margin-bottom:10px;overflow-wrap:anywhere}.pair{display:grid;grid-template-columns:1fr 1fr;gap:10px}.pane{min-width:0;background:white;padding:8px}.stage{overflow:auto;max-height:70vh;background:#78658d}.stage img{display:block;max-width:none}.checker{background-color:#eee;background-image:conic-gradient(#bbb 25%,#eee 0 50%,#bbb 0 75%,#eee 0);background-size:24px 24px}.crop{overflow:hidden;background:#78658d}.crop img{display:block;max-width:none}#crops{display:flex;gap:12px;overflow:auto;margin:10px 0}.hash{font-size:11px;color:#555}@media(max-width:700px){.pair{grid-template-columns:1fr}}</style>
<header><b>People symbols</b><button id="prev">←</button><button id="next">→</button><span id="count"></span><select id="filter"><option value="accepted">Accepted</option><option value="all">All processed</option><option value="context">Context references</option></select><input id="search" placeholder="Concept, style or ID"><select id="bg"><option value="purple">Purple</option><option value="checker">Checker</option></select><select id="zoom"><option value="1">Native 1×</option><option value="0.5">0.5×</option><option value="2">2×</option></select></header><main id="app"></main><script>
const DATA=__DATA__,$=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let list=[],i=0;
function filter(){let s=$('search').value.toLowerCase();list=DATA.filter(x=>($('filter').value==='context'?x.review_required===false:($('filter').value==='all'?x.newly_processed:x.accepted))&&(!s||[x.id,x.style,x.concept].join(' ').toLowerCase().includes(s)));i=0;render()}
function pane(src,label,x,z){return `<section class="pane"><b>${esc(label)}</b><div class="stage ${$('bg').value==='checker'?'checker':''}"><img src="${esc(src)}" width="${x.dimensions[0]*z}" height="${x.dimensions[1]*z}" alt="${esc(label+' '+x.id)}"></div></section>`}
function render(){let x=list[i];$('count').textContent=`${list.length?i+1:0} / ${list.length}`;if(!x){$('app').textContent='No matching results.';return}let z=+$('zoom').value;$('app').innerHTML=`<section class="meta"><b>${esc(x.id)} · ${esc(x.style)} · ${esc(x.concept)}</b><p>${x.review_required===false?'Context reference':x.accepted?'Accepted':'Original retained'} · native ${x.dimensions.join('×')} · original ${x.source_bytes} bytes · delivered ${x.after_bytes} bytes</p><p>${esc(x.reason)}</p><div class="hash">Source SHA ${esc(x.source_sha256)}<br>Delivered SHA ${esc(x.output_sha256)}</div><p>${x.regions.map((r,n)=>`<button data-region="${n}">${esc(r.name)}</button>`).join(' ')}</p><div id="crops"></div></section><div class="pair">${pane(x.source,'BEFORE',x,z)}${pane(x.after,x.accepted?'AFTER · accepted lossless WebP':'AFTER · original retained',x,z)}</div>`;document.querySelectorAll('[data-region]').forEach(b=>b.onclick=()=>{let r=x.regions[+b.dataset.region],[a,c,d,e]=r.roi,w=d-a,h=e-c;$('crops').innerHTML=[[x.source,'Before ROI'],[x.after,'Accepted ROI']].map(([src,title])=>`<div><b>${title}</b><div class="crop ${$('bg').value==='checker'?'checker':''}" style="width:${w*z}px;height:${h*z}px"><img src="${esc(src)}" width="${x.dimensions[0]*z}" height="${x.dimensions[1]*z}" style="transform:translate(${-a*z}px,${-c*z}px)"></div></div>`).join('')})}
$('prev').onclick=()=>{if(list.length)i=(i+list.length-1)%list.length;render()};$('next').onclick=()=>{if(list.length)i=(i+1)%list.length;render()};$('filter').onchange=filter;$('search').oninput=filter;$('bg').onchange=render;$('zoom').onchange=render;filter();
</script></html>'''.replace('__DATA__',payload)
 out=batch/'review.html';out.write_text(page);assert 'selected_outputs' not in page and 'q80' not in page.lower();print(json.dumps({'review_html':str(out),'rows':len(cards),'accepted':sum(c['accepted'] for c in cards)}))
if __name__=='__main__':main()
